#include<bits/stdc++.h>

using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<int> a(m);
    for (int &i: a) {
        cin >> i;
    }

    // k = 1,2,...,M について操作を行った場合に、1,2,...,N がそれぞれどこに行くかを求める
    vector<int> b(n + 1);
    iota(b.begin(), b.end(), 0);
    for (int i: a) {
        swap(b[i], b[i + 1]);
    }
    vector<int> pos(n + 1);
    for (int i = 1; i <= n; i++) {
        pos[b[i]] = i;
    }

    // 答えを求める
    iota(b.begin(), b.end(), 0);
    for (int i: a) {
        if (b[i] == 1) {
            cout << pos[b[i + 1]] << '\n';
        } else if (b[i + 1] == 1) {
            cout << pos[b[i]] << '\n';
        } else {
            cout << pos[1] << '\n';
        }
        swap(b[i], b[i + 1]);
    }
}

#include<bits/stdc++.h>

using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<int> a(m);
    for (int &i: a) {
        cin >> i;
    }

    // st[j] に i が含まれる
    //   <=> a[i] を無視して操作したとき、b[j] = 1
    vector <set<int>> st(n + 1);
    for (int i = 0; i < m; i++) {
        st[1].insert(i);
    }

    for (int i = 0; i < m; i++) {
        swap(st[a[i]], st[a[i] + 1]);
        if (st[a[i]].count(i)) {
            st[a[i]].erase(i);
            st[a[i] + 1].insert(i);
        } else if (st[a[i] + 1].count(i)) {
            st[a[i] + 1].erase(i);
            st[a[i]].insert(i);
        }
    }

    vector<int> ans(m);
    for (int i = 1; i <= n; i++) {
        for (int j: st[i]) ans[j] = i;
    }
    for (int i: ans) cout << i << '\n';
}
